// Compares tgit's merge of two commits (merged tree, conflicted stages) with the real git's
// `merge-tree --write-tree`, which runs the same merge-ort code, on random histories with
// criss-cross merges, built with `git fast-import`.
// Usage: node test/fuzz/merge-fuzz.ts [--count 200] [--seed 1]
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { parseArgs } from "node:util";
import { mergeCommits } from "../../src/core/merge/ort.ts";
import { mergeBases } from "../../src/core/revision/merge-base.ts";
import { mutate, randomFile, rng } from "./random-text.ts";

const { values } = parseArgs({
  options: {
    count: { type: "string", default: "200" },
    seed: { type: "string", default: "1" },
  },
});
const rand = rng(Number(values.seed));
const pick = <T>(items: T[]): T => items[Math.floor(rand() * items.length)] as T;
