/** File metadata cached in the index, used by the real git to detect changes quickly. */
export interface StatData {
  ctimeSec: number;
  ctimeNsec: number;
  mtimeSec: number;
  mtimeNsec: number;
  dev: number;
  ino: number;
  uid: number;
  gid: number;
  size: number;
}

export interface IndexEntry {
  path: string;
  oid: string;
  /** The mode as a number, e.g. 0o100644. */
  mode: number;
  stat: StatData;
  /** The merge stage: 0 for a normal entry, 1 (base), 2 (ours), or 3 (theirs) for a conflict. */
  stage?: number;
}

export const EMPTY_STAT: StatData = { ctimeSec: 0, ctimeNsec: 0, mtimeSec: 0, mtimeNsec: 0, dev: 0, ino: 0, uid: 0, gid: 0, size: 0 };

function stageOf(entry: IndexEntry): number {
  return entry.stage ?? 0;
}

/**
 * The staging area (`.git/index`), holding one entry per path, or for a path with a merge conflict,
 * one entry per stage instead.
 */
export class Index {
  private readonly entries = new Map<string, IndexEntry>();
  private readonly conflicts = new Map<string, IndexEntry[]>();
  /** Whether entries were added, removed, or changed since the index was read. */
  changed = false;

  /** The stage 0 entry of a path. */
  get(filePath: string): IndexEntry | undefined {
    return this.entries.get(filePath);
  }

  /** Whether the path is tracked, merged or not. */
  has(filePath: string): boolean {
    return this.entries.has(filePath) || this.conflicts.has(filePath);
  }

  /** The number of entries, counting each stage of a conflict. */
  get size(): number {
    let size = this.entries.size;
    for (const stages of this.conflicts.values()) size += stages.length;
    return size;
  }

  /** Sets the stage 0 entry of a path, which resolves a conflict there. */
  set(entry: IndexEntry): void {
    const old = this.entries.get(entry.path);
    if (!old || old.oid !== entry.oid || old.mode !== entry.mode) this.changed = true;
    if (this.conflicts.delete(entry.path)) this.changed = true;
    this.entries.set(entry.path, { ...entry, stage: undefined });
  }

  /** Records a conflict: the path's entries for stages 1 to 3 (some may be missing) replace its entry. */
  setConflict(filePath: string, stages: IndexEntry[]): void {
    this.entries.delete(filePath);
    this.conflicts.set(filePath, [...stages].sort((a, b) => stageOf(a) - stageOf(b)));
    this.changed = true;
  }

  /** Removes every entry of a path. */
  delete(filePath: string): void {
    if (this.entries.delete(filePath)) this.changed = true;
    if (this.conflicts.delete(filePath)) this.changed = true;
  }

  /** The stage 0 entries in index order (bytewise by path). */
  list(): IndexEntry[] {
    return [...this.entries.values()].sort((a, b) => comparePaths(a.path, b.path));
  }

  /** The stage 1 to 3 entries of a path with a conflict (empty if it has none). */
  stages(filePath: string): IndexEntry[] {
    return this.conflicts.get(filePath) ?? [];
  }

  /** The paths with a conflict, in index order. */
  unmergedPaths(): string[] {
    return [...this.conflicts.keys()].sort(comparePaths);
  }

  /** Every tracked path, merged or not, in index order. */
  paths(): string[] {
    return [...this.entries.keys(), ...this.conflicts.keys()].sort(comparePaths);
  }

  /** Every entry of every stage, in index order (by path, then stage). */
  allEntries(): IndexEntry[] {
    return this.paths().flatMap((filePath) => {
      const entry = this.entries.get(filePath);
      return entry ? [entry] : this.stages(filePath);
    });
  }

  /** Every directory that contains at least one entry, e.g. "d" and "d/e" for "d/e/f.txt". */
  directories(): Set<string> {
    const dirs = new Set<string>();
    for (const filePath of this.paths()) {
      for (let slash = filePath.indexOf("/"); slash >= 0; slash = filePath.indexOf("/", slash + 1)) {
        dirs.add(filePath.slice(0, slash));
      }
    }
    return dirs;
  }
}

