/** The author or committer identity, from GIT_<ROLE>_NAME/EMAIL/DATE or `user.name`/`user.email`. */
export function identFor(role: IdentRole, repo: Repository, env: NodeJS.ProcessEnv): Ident {
  const name = env[`GIT_${role}_NAME`] ?? repo.config.get("user.name");
  const email = env[`GIT_${role}_EMAIL`] ?? repo.config.get("user.email");
  if (name === undefined || email === undefined || name.trim() === "") {
    throw fatal("unable to auto-detect name and email address; set user.name and user.email");
  }
  const dateText = env[`GIT_${role}_DATE`];
  let date: { timestamp: number; tz: string } | null;
  if (dateText === undefined) {
    const timestamp = Math.floor(Date.now() / 1000);
    date = { timestamp, tz: localTimezone(timestamp) };
  } else {
    date = parseDate(dateText);
    if (!date) throw fatal(`invalid date format: ${dateText}`);
  }
