import { readObject } from "./store.ts";

export interface Commit {
  tree: string;
  parents: string[];
  /** Identity lines as stored: "Name <email> 1700000000 +0000". */
  author: string;
  committer: string;
  message: string;
}

export function parseCommit(data: Buffer): Commit {
  const text = data.toString("utf8");
  const end = text.indexOf("\n\n");
  const headerText = end < 0 ? text : text.slice(0, end);
  const commit: Commit = { tree: "", parents: [], author: "", committer: "", message: end < 0 ? "" : text.slice(end + 2) };
  for (const line of headerText.split("\n")) {
    const space = line.indexOf(" ");
    const key = line.slice(0, space);
    const value = line.slice(space + 1);
    if (key === "tree") commit.tree = value;
    else if (key === "parent") commit.parents.push(value);
    else if (key === "author") commit.author = value;
    else if (key === "committer") commit.committer = value;
  }
  return commit;
}

export function serializeCommit(commit: Commit): Buffer {
  const lines = [`tree ${commit.tree}`, ...commit.parents.map((p) => `parent ${p}`)];
  lines.push(`author ${commit.author}`, `committer ${commit.committer}`);
  return Buffer.from(`${lines.join("\n")}\n\n${commit.message}`, "utf8");
}

/** Reads a commit, or returns null if the object is missing or is not a commit. */
export function readCommit(gitDir: string, oid: string): Commit | null {
  const object = readObject(gitDir, oid);
  return object?.type === "commit" ? parseCommit(object.data) : null;
}

export interface Ident {
  name: string;
  email: string;
  timestamp: number;
  tz: string;
}

/** Parses an identity line: "Name <email> 1700000000 +0000". */
export function parseIdent(line: string): Ident {
  const match = /^(.*?) ?<([^>]*)> ?(\d+)? ?([+-]\d+)?$/.exec(line);
  if (!match) return { name: line, email: "", timestamp: 0, tz: "+0000" };
  return { name: match[1] as string, email: match[2] as string, timestamp: Number(match[3] ?? 0), tz: match[4] ?? "+0000" };
}

export function formatIdent(ident: Ident): string {
  return `${ident.name} <${ident.email}> ${ident.timestamp} ${ident.tz}`;
}

/** The message lines without the blank lines at the start and the end. */
export function messageLines(message: string): string[] {
  const lines = message.split("\n");
  while (lines.length > 0 && (lines[0] as string).trim() === "") lines.shift();
  while (lines.length > 0 && (lines.at(-1) as string).trim() === "") lines.pop();
  return lines;
}

/** The subject, as `--oneline` shows it: the lines of the first paragraph, joined with spaces. */
export function commitSubject(commit: Commit): string {
  const lines = messageLines(commit.message);
  const end = lines.indexOf("");
  return (end < 0 ? lines : lines.slice(0, end)).map((line) => line.trim()).join(" ");
}
export function resolveHead(gitDir: string): string | null {
  return readRef(gitDir, "HEAD");
}

/** Points HEAD at a branch. */
export function setHeadToBranch(gitDir: string, ref: string): void {
  fs.writeFileSync(path.join(gitDir, "HEAD"), `ref: ${ref}\n`);
}

/** Creates or updates a ref; fails like the real git if it conflicts with an existing ref's path. */
export function writeRef(gitDir: string, name: string, oid: string): void {
  const file = path.join(gitDir, name);
  const parts = name.split("/");
  for (let i = 1; i < parts.length; i++) {
    const prefix = parts.slice(0, i).join("/");
    if (fs.existsSync(path.join(gitDir, prefix)) && !fs.statSync(path.join(gitDir, prefix)).isDirectory()) {
      throw fatal(`cannot lock ref '${name}': '${prefix}' exists; cannot create '${name}'`);
    }
  }
  if (fs.existsSync(file) && fs.statSync(file).isDirectory()) {
    const inside = listRefs(gitDir, `${name}/`)[0]?.name ?? `${name}/`;
    throw fatal(`cannot lock ref '${name}': '${inside}' exists; cannot create '${name}'`);
  }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const lock = `${file}.lock`;
  fs.writeFileSync(lock, `${oid}\n`);
  fs.renameSync(lock, file);
}

/** Deletes a ref and any directories under `refs/` left empty. */
export function deleteRef(gitDir: string, name: string): void {
  fs.rmSync(path.join(gitDir, name), { force: true });

