import fs from "node:fs";
import path from "node:path";
import type { CommandContext } from "../cli/context.ts";
import { usageError } from "../cli/errors.ts";
import { hasOption, parseOptions } from "../cli/options.ts";
import { identFor } from "../core/ident/ident.ts";
import { indexPath, readIndex, writeIndex, type Index } from "../core/index/index-file.ts";
import { formatIdent, readCommit, serializeCommit } from "../core/objects/commit.ts";
import { writeObject } from "../core/objects/store.ts";
import { writeTreeFromFiles } from "../core/objects/tree.ts";
import { HEADS_PREFIX, readHead, resolveHead, writeRef } from "../core/refs/refs.ts";
import type { Repository } from "../core/repo/repository.ts";
import { requireRepository } from "../core/repo/repository.ts";
import { Abbreviator } from "../core/revision/abbrev.ts";
import { indexFiles } from "../core/status/changes.ts";
import { hashWorktreeFile, toIndexEntry } from "../core/worktree/files.ts";

/** Updates the index with the working tree's version of every tracked file (`commit -a`). */
function stageTrackedFiles(repo: Repository, index: Index): void {
  const filemode = repo.config.getBool("core.filemode", true);
  for (const entry of index.list()) {
    const file = hashWorktreeFile(repo.gitDir, path.join(repo.workTree, entry.path), { filemode, previousMode: entry.mode, write: true });
    if (file) index.set(toIndexEntry(entry.path, file));
    else index.delete(entry.path);
  }
}

export function commit(ctx: CommandContext): number {
  const parsed = parseOptions(ctx.args, [
    { name: "message", short: "m", long: "message", takesValue: true },
    { name: "all", short: "a", long: "all" },
  ]);
  if (parsed.positionals.length > 0) throw usageError("committing only some paths is not supported");
  const repo = requireRepository(ctx.cwd, ctx.env);
  const index = readIndex(repo.gitDir);
  const all = hasOption(parsed, "all");
  if (all) stageTrackedFiles(repo, index);

  const tree = writeTreeFromFiles(repo.gitDir, indexFiles(index));
  // Without -a the real git refreshes and writes the index even when the commit fails.
  if (!all && (index.changed || !fs.existsSync(indexPath(repo.gitDir)))) writeIndex(repo.gitDir, index);

  const parent = resolveHead(repo.gitDir);
  const parentTree = parent === null ? null : readCommit(repo.gitDir, parent)?.tree;
  if (tree === parentTree || (parent === null && index.size === 0)) {
    ctx.stdout("nothing to commit, working tree clean\n");
    return 1;
  }
  const message = cleanupMessage(joinMessages(parsed.options.get("message") ?? []));
  if (message === "") {
    ctx.stderr("Aborting commit due to empty commit message.\n");
    return 1;
  }

  const oid = writeObject(
    repo.gitDir,
    "commit",
    serializeCommit({
      tree,
      parents: parent === null ? [] : [parent],
      author: formatIdent(identFor("AUTHOR", repo, ctx.env)),
      committer: formatIdent(identFor("COMMITTER", repo, ctx.env)),
      message,
    }),
  );
  const head = readHead(repo.gitDir);
  writeRef(repo.gitDir, head.kind === "branch" ? head.ref : "HEAD", oid);
  if (all) writeIndex(repo.gitDir, index);

  const where = head.kind === "branch" ? head.ref.replace(HEADS_PREFIX, "") : "detached HEAD";
  const root = parent === null ? " (root-commit)" : "";
  ctx.stdout(`[${where}${root} ${new Abbreviator(repo.gitDir).abbreviate(oid)}] ${message.split("\n")[0]}\n`);
  return 0;
}
import { identFor } from "../ident/ident.ts";
import type { Repository } from "../repo/repository.ts";
import { formatIdent, serializeCommit } from "./commit.ts";
import { writeObject } from "./store.ts";

/** Writes a commit by the author and committer configured for the repository and environment. */
export function writeCommit(repo: Repository, env: NodeJS.ProcessEnv, tree: string, parents: string[], message: string): string {
  return writeObject(
    repo.gitDir,
    "commit",
    serializeCommit({
      tree,
      parents,
      author: formatIdent(identFor("AUTHOR", repo, env)),
      committer: formatIdent(identFor("COMMITTER", repo, env)),
      message,
    }),
  );
}
export class Index {
  private readonly entries = new Map<string, IndexEntry>();
  private readonly conflicts = new Map<string, IndexEntry[]>();
  /** Whether entries were added, removed, or changed since the index was read. */
  changed = false;

  /** The stage 0 entry of a path. */
  get(filePath: string): IndexEntry | undefined {
    return this.entries.get(filePath);
  }

  /** Whether the path is tracked, merged or not. */
  has(filePath: string): boolean {
    return this.entries.has(filePath) || this.conflicts.has(filePath);
  }

  /** The number of entries, counting each stage of a conflict. */
  get size(): number {
    let size = this.entries.size;
    for (const stages of this.conflicts.values()) size += stages.length;
    return size;
  }

  /** Sets the stage 0 entry of a path, which resolves a conflict there. */
  set(entry: IndexEntry): void {
    const old = this.entries.get(entry.path);
    if (!old || old.oid !== entry.oid || old.mode !== entry.mode) this.changed = true;
    if (this.conflicts.delete(entry.path)) this.changed = true;
    this.entries.set(entry.path, { ...entry, stage: undefined });
  }

  /** Records a conflict: the path's entries for stages 1 to 3 (some may be missing) replace its entry. */
  setConflict(filePath: string, stages: IndexEntry[]): void {
    this.entries.delete(filePath);
    this.conflicts.set(filePath, [...stages].sort((a, b) => stageOf(a) - stageOf(b)));
    this.changed = true;
  }

  /** Removes every entry of a path. */
  delete(filePath: string): void {
    if (this.entries.delete(filePath)) this.changed = true;
    if (this.conflicts.delete(filePath)) this.changed = true;
  }

  /** The stage 0 entries in index order (bytewise by path). */
  list(): IndexEntry[] {
    return [...this.entries.values()].sort((a, b) => comparePaths(a.path, b.path));
  }

  /** The stage 1 to 3 entries of a path with a conflict (empty if it has none). */
  stages(filePath: string): IndexEntry[] {
    return this.conflicts.get(filePath) ?? [];
  }

  /** The paths with a conflict, in index order. */
  unmergedPaths(): string[] {
    return [...this.conflicts.keys()].sort(comparePaths);
  }

  /** Every tracked path, merged or not, in index order. */
  paths(): string[] {
    return [...this.entries.keys(), ...this.conflicts.keys()].sort(comparePaths);
  }

  /** Every entry of every stage, in index order (by path, then stage). */
  allEntries(): IndexEntry[] {
    return this.paths().flatMap((filePath) => {
      const entry = this.entries.get(filePath);
      return entry ? [entry] : this.stages(filePath);
    });
  }

  /** Every directory that contains at least one entry, e.g. "d" and "d/e" for "d/e/f.txt". */
  directories(): Set<string> {
    const dirs = new Set<string>();
    for (const filePath of this.paths()) {
      for (let slash = filePath.indexOf("/"); slash >= 0; slash = filePath.indexOf("/", slash + 1)) {
        dirs.add(filePath.slice(0, slash));
      }
    }
    return dirs;
  }
}

export function indexPath(gitDir: string): string {
  return path.join(gitDir, "index");
}
