  if (ref?.startsWith(HEADS_PREFIX)) return `branch '${arg}'`;

  // <branch>^..., <branch>~<n>, or <branch>~: the early part of a branch (except for <branch>~0).
  let suffix = /\^+$/.exec(arg)?.[0];
  let early = suffix !== undefined;
  if (!early) {
    suffix = /~\d*$/.exec(arg)?.[0];
    early = suffix !== undefined && (suffix === "~" || /[1-9]/.test(suffix));
  }
  if (suffix !== undefined) {
    const branch = arg.slice(0, -suffix.length);
    if (readRef(gitDir, HEADS_PREFIX + branch) !== null) return `branch '${branch}'${early ? " (early part)" : ""}`;
  }
