    reportCheckoutProblems(ctx, problems, MERGE_ACTION);
    ctx.stderr("Merge with strategy ort failed.\n");
    return 2;
  }
  recordConflicts(index, result);
  writeIndex(repo.gitDir, index);

  const messages = parsed.options.get("message");
  const message = messages ? messages.join("\n\n") : defaultMessage(repo.gitDir, arg);
  if (result.conflicts.length > 0) {
    const conflicts = index.unmergedPaths().map((p) => `#\t${p}\n`).join("");
    writeMergeState(repo.gitDir, theirs, `${message}\n\n# Conflicts:\n${conflicts}`);
    ctx.stdout("Automatic merge failed; fix conflicts and then commit the result.\n");
    return 1;
  }
  updateHead(repo.gitDir, writeCommit(repo, ctx.env, result.tree, [head, theirs], cleanupMessage(`${message}\n`)));
  ctx.stdout("Merge made by the 'ort' strategy.\n");
  return 0;
}

