test("writes and reads conflict stages, and resolves them with a stage 0 entry", () => {
  const gitDir = fs.mkdtempSync(path.join(os.tmpdir(), "tgit-unit-"));
  try {
    const index = new Index();
    const oid = "e69de29bb2d1d6434b8b29ae775ad8c2e48c5391";
    index.set({ path: "a.txt", oid, mode: 0o100644, stat: EMPTY_STAT });
    index.set({ path: "c.txt", oid, mode: 0o100644, stat: EMPTY_STAT });
    index.setConflict("b.txt", [3, 2].map((stage) => ({ path: "b.txt", oid, mode: 0o100644, stat: EMPTY_STAT, stage })));
    writeIndex(gitDir, index);
    const read = readIndex(gitDir);
    assert.deepEqual(read.unmergedPaths(), ["b.txt"]);
    assert.deepEqual(
      read.allEntries().map((e) => `${e.path} ${e.stage ?? 0}`),
      ["a.txt 0", "b.txt 2", "b.txt 3", "c.txt 0"],
    );
    assert.equal(read.size, 4);
    read.set({ path: "b.txt", oid, mode: 0o100644, stat: EMPTY_STAT });
    assert.deepEqual(read.unmergedPaths(), []);
    assert.deepEqual(read.paths(), ["a.txt", "b.txt", "c.txt"]);
  } finally {
    fs.rmSync(gitDir, { recursive: true, force: true });
  }
});
EOF
