const fs = require("fs");
const f = "docs/notes/v2-git-behavior.md";
let s = fs.readFileSync(f, "utf8");
const anchor = "- While `MERGE_HEAD` exists, `switch` fails: `fatal: cannot switch branch while merging`, 128.";
if (!s.includes(anchor)) throw new Error("anchor missing");
s = s.replace(anchor, `${anchor} The check comes after the target
  is resolved, so an unknown branch or an existing \`-c\` name fails with its own message first.`);
const anchor2 = "- `-m <msg>`: the message instead (several `-m` are joined as paragraphs). A fast-forward ignores it.";
if (!s.includes(anchor2)) throw new Error("anchor2 missing");
s = s.replace(anchor2, `${anchor2}
  Unlike \`commit\`, merge joins the \`-m\` values with \`\\n\\n\` as they are and adds one \`\\n\`: \`-m $'a\\n' -m $'b\\n\\n'\`
  gives \`MERGE_MSG\` \`a\\n\\n\\nb\\n\\n\\n\\n# Conflicts:\\n#\\ta.txt\\n\`. The commit of a clean merge cleans this up.
- Naming (\`merge_name\`): the argument is looked up as a ref first; if it is a branch (\`topic\`, \`heads/topic\`,
  \`refs/heads/topic\`), the message names it as given. Otherwise a trailing run of \`^\`, or a trailing \`~<digits>\`
  or \`~\`, is cut off, and if what remains is a branch: \`Merge branch 'topic' (early part)\`, except for \`~0\`
  (\`~00\`, ...), which gives \`Merge branch 'topic'\`. \`topic~1^\` and abbreviated IDs give \`Merge commit '<arg>'\`.
- Into a branch with no commits yet: a two-way checkout from the empty tree to the other commit (staged files
  that the commit does not have are kept), then the branch points at it; \`-m\` is ignored. If an untracked or
  staged file is in the way: \`fatal: read-tree failed\`, 128, nothing changed.`);
fs.writeFileSync(f, s);
EOF
